<?php
namespace App\Services;
use App\Models\Payment;use App\Models\PaymentWebhookEvent;use Illuminate\Support\Arr;use Illuminate\Support\Facades\DB;
final class WompiPaymentService{
 public function configured():bool{return (bool)config('payments.wompi.enabled')&&filled(config('payments.wompi.public_key'))&&filled(config('payments.wompi.integrity_secret'))&&filled(config('payments.wompi.events_secret'));}
 public function checkout(Payment $payment):array{if(!$this->configured())throw new \RuntimeException('Wompi no esta configurado.');$reference=$payment->provider_reference;$cents=(int)$payment->amount_in_cents;$currency=$payment->currency;return ['url'=>config('payments.wompi.checkout_url'),'public_key'=>config('payments.wompi.public_key'),'currency'=>$currency,'amount_in_cents'=>$cents,'reference'=>$reference,'signature'=>hash('sha256',$reference.$cents.$currency.config('payments.wompi.integrity_secret')),'redirect_url'=>route('payment.wompi.return',$payment->trip_id),'email'=>$payment->user->email,'name'=>$payment->user->name];}
 public function verify(array $payload,?string $headerChecksum=null):string{if(($payload['environment']??null)!==config('payments.wompi.environment'))throw new \InvalidArgumentException('Ambiente Wompi invalido.');$properties=Arr::get($payload,'signature.properties');$checksum=strtolower((string)(Arr::get($payload,'signature.checksum')?:$headerChecksum));if(!is_array($properties)||!$checksum||!isset($payload['timestamp']))throw new \InvalidArgumentException('Firma incompleta.');$source='';foreach($properties as $property){$value=Arr::get($payload['data']??[],$property,'__missing__');if($value==='__missing__'||is_array($value)||is_object($value))throw new \InvalidArgumentException('Propiedad firmada invalida.');$source.=(string)$value;}$expected=hash('sha256',$source.(string)$payload['timestamp'].config('payments.wompi.events_secret'));if(!hash_equals($expected,$checksum))throw new \InvalidArgumentException('Firma invalida.');return $checksum;}
 public function handle(array $payload,?string $headerChecksum=null):void{$checksum=$this->verify($payload,$headerChecksum);if(($payload['event']??null)!=='transaction.updated')return;$tx=Arr::get($payload,'data.transaction');if(!is_array($tx))throw new \InvalidArgumentException('Transaccion ausente.');DB::transaction(function()use($payload,$checksum,$tx){$event=PaymentWebhookEvent::firstOrCreate(['provider'=>'wompi','checksum'=>$checksum],['event_type'=>$payload['event'],'external_id'=>$tx['id']??null,'payload'=>['event'=>$payload['event'],'environment'=>$payload['environment']??null,'timestamp'=>$payload['timestamp']??null,'transaction'=>['id'=>$tx['id']??null,'status'=>$tx['status']??null,'reference'=>$tx['reference']??null,'amount_in_cents'=>$tx['amount_in_cents']??null,'currency'=>$tx['currency']??null,'payment_method_type'=>$tx['payment_method_type']??null]]]);if($event->processed_at)return;$payment=Payment::where('provider_reference',$tx['reference']??'')->lockForUpdate()->firstOrFail();abort_unless((int)$payment->amount_in_cents===(int)($tx['amount_in_cents']??-1)&&$payment->currency===($tx['currency']??null),422,'Monto o moneda no coincide.');$status=strtoupper((string)($tx['status']??''));$mapped=match($status){'APPROVED'=>'completed','DECLINED','ERROR'=>'failed','VOIDED'=>'cancelled',default=>'pending'};$payment->update(['status'=>$mapped,'provider_transaction_id'=>$tx['id']??$payment->provider_transaction_id,'payment_method'=>$tx['payment_method_type']??$payment->payment_method,'paid_at'=>$mapped==='completed'?now():$payment->paid_at,'failed_at'=>$mapped==='failed'?now():null]);if($mapped==='completed'&&$payment->trip?->status==='completed'){app(MonetizationService::class)->recordCompletedTrip($payment->trip);app(MonetizationService::class)->makeAvailable($payment->trip_id);}$event->update(['processed_at'=>now()]);});}
}